fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    let mut result = Vec::with_capacity(a.len());
    
    for s in a {
        if maxsplit == 0 {
            // No splitting allowed, return the original string as a single element
            result.push(vec![s]);
        } else {
            // Convert maxsplit to usize for rsplitn
            // rsplitn takes n as the maximum number of parts to return
            let parts: Vec<String> = s.rsplitn(maxsplit as usize + 1, &sep)
                .map(|part| part.to_string())
                .collect();
            
            // Since rsplitn returns parts from right to left, we need to reverse
            // to maintain the original order of parts
            let mut reversed_parts: Vec<String> = parts.into_iter().rev().collect();
            
            // Ensure we have at least one element (handles empty string case)
            if reversed_parts.is_empty() {
                reversed_parts.push(String::new());
            }
            
            result.push(reversed_parts);
        }
    }
    
    result
}